/* DAWAH X — darimi, অধ্যায় 15 · খণ্ড 15 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['darimi'][15]=[[2801,2801,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُقَاسِمُ بِالْجَدِّ مَعَ الْإِخْوَةِ إِلَى الثُّلُثِ ثُمَّ لَا يُنْقِصُهُ ‏","","",""],[2802,2802,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ يُونُسَ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏خُذْ مِنْ أَمْرِ الْجَدِّ مَا اجْتَمَعَ النَّاسُ عَلَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْنِي قَوْلَ ‏ ‏زَيْدٍ ‏","","",""],[2803,2803,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ فِي أُخْتٍ وَأُمٍّ وَزَوْجٍ وَجَدٍّ قَالَ ‏ ‏جَعَلَهَا مِنْ سَبْعٍ وَعِشْرِينَ لِلْأُمِّ سِتَّةٌ وَلِلزَّوْجِ تِسْعَةٌ وَلِلْجَدِّ ثَمَانِيَةٌ وَلِلْأُخْتِ أَرْبَعَةٌ ‏","","",""],[2804,2804,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْعَثُ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنَّ أَوَّلَ جَدَّةٍ أُطْعِمَتْ فِي الْإِسْلَامِ سَهْمًا أَمُّ أَبٍ وَابْنُهَا حَيٌّ ‏","","",""],[2805,2805,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَطْعَمَ جَدَّةً سُدُسًا ‏","","",""],[2806,2806,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏وَرَّثَ جَدَّةً مَعَ ابْنِهَا ‏","","",""],[2807,2807,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏مَنْصُورُ بْنُ الْمُعْتَمِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏أَطْعَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَ جَدَّاتٍ سُدُسًا قَالَ قُلْتُ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏مَنْ ‏ ‏هُنَّهْ قَالَ جَدَّتَاكَ مِنْ قِبَلِ أَبِيكَ وَجَدَّتُكَ مِنْ قِبَلِ أُمِّكَ ‏","","",""],[2808,2808,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏الْحَسَنُ ‏ ‏قَالَ ‏ ‏تَرِثُ الْجَدَّةُ وَابْنُهَا حَيٌّ ‏","","",""],[2809,2809,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏لَا تَرِثُ أُمُّ ‏ ‏أَبِ الْأُمِّ ابْنُهَا الَّذِي ‏ ‏تُدْلِي ‏ ‏بِهِ لَا يَرِثُ فَكَيْفَ تَرِثُ هِيَ ‏","","",""],[2810,2810,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ابْنِ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّهْمَاءِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏تَرِثُ الْجَدَّةُ وَابْنُهَا حَيٌّ ‏","","",""],[2811,2811,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَشْعَثُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَتْ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏جَدَّةٌ أُمُّ أَبٍ ‏ ‏أَوْ أُمُّ أُمٍّ ‏ ‏فَقَالَتْ إِنَّ ابْنَ ابْنِي ‏ ‏أَوْ ابْنَ ابْنَتِي ‏ ‏تُوُفِّيَ وَبَلَغَنِي أَنَّ لِي نَصِيبًا فَمَا لِي فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏مَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِيهَا شَيْئًا وَسَأَسْأَلُ النَّاسَ ‏ ‏فَلَمَّا صَلَّى الظُّهْرَ قَالَ أَيُّكُمْ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي الْجَدَّةِ شَيْئًا ‏ ‏فَقَالَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏أَنَا قَالَ مَاذَا قَالَ ‏ ‏أَعْطَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُدُسًا قَالَ أَيَعْلَمُ ذَاكَ أَحَدٌ غَيْرُكَ فَقَالَ ‏ ‏مُحَمَّدُ بْنُ مَسْلَمَةَ ‏ ‏صَدَقَ فَأَعْطَاهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏السُّدُسَ فَجَاءَتْ إِلَى ‏ ‏عُمَرَ ‏ ‏مِثْلُهَا ‏ ‏فَقَالَ ‏ ‏مَا أَدْرِي مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا شَيْئًا وَسَأَسْأَلُ النَّاسَ فَحَدَّثُوهُ بِحَدِيثِ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏وَمُحَمَّدِ بْنِ مَسْلَمَةَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَيُّكُمَا خَلَتْ بِهِ فَلَهَا السُّدُسُ فَإِنْ اجْتَمَعْتُمَا فَهُوَ بَيْنَكُمَا ‏","","",""],[2812,2812,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْعَثُ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَزَيْدٍ ‏ ‏قَالَا ‏ ‏إِذَا كَانَتْ الْجَدَّاتُ سَوَاءً وَرِثَ ثَلَاثُ جَدَّاتٍ جَدَّتَا أَبِيهِ أُمُّ أُمِّهِ وَأُمُّ أَبِيهِ وَجَدَّةُ أُمِّهِ فَإِنْ كَانَتْ إِحَدَاهُنَّ أَقْرَبَ فَالسَّهْمُ لِذَوِي الْقُرْبَى ‏","","",""],[2813,2813,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَزَيْدٍ ‏ ‏أَنَّهُمَا كَانَا لَا يُوَرِّثَانِ الْجَدَّةَ أُمَّ الْأَبِ مَعَ الْأَبِ ‏","","",""],[2814,2814,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏كَانَ ‏ ‏لَا يُوَرِّثُ الْجَدَّةَ وَابْنُهَا حَيٌّ ‏","","",""],[2815,2815,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَشْعَثُ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنَّ الْجَدَّاتِ لَيْسَ لَهُنَّ مِيرَاثٌ إِنَّمَا هِيَ طُعْمَةٌ أُطْعِمْنَهَا وَالْجَدَّاتُ أَقْرَبُهُنَّ وَأَبْعَدُهُنَّ سَوَاءٌ ‏","","",""],[2816,2816,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏تَرِثُ الْجَدَّةُ وَابْنُهَا حَيٌّ ‏","","",""],[2817,2817,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَشْعَثُ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏جِئْنَ أَرْبَعُ جَدَّاتٍ ‏ ‏يَتَسَاوَقْنَ ‏ ‏إِلَى ‏ ‏مَسْرُوقٍ ‏ ‏فَأَلْقَى ‏ ‏أَمَّ ‏ ‏أَبِ الْأَبِ وَوَرَّثَ ثَلَاثًا جَدَّتَيْ أَبِيهِ أُمَّ أُمِّهِ وَأُمَّ أَبِيهِ وَجَدَّةَ أُمِّهِ ‏","","",""],[2818,2818,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏فِي ابْنَةٍ وَابْنَةِ ابْنٍ قَالَ ‏ ‏النِّصْفُ وَالسُّدُسُ وَمَا بَقِيَ ‏ ‏فَرَدٌّ ‏ ‏عَلَى الْبِنْتِ ‏","","",""],[2819,2819,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ ‏ ‏أُتِيَ فِي إِخْوَةٍ لِأُمٍّ وَأُمٍّ فَأَعْطَى الْإِخْوَةَ مِنْ الْأُمِّ الثُّلُثَ وَالْأُمَّ سَائِرَ الْمَالِ وَقَالَ الْأُمُّ ‏ ‏عَصَبَةُ ‏ ‏مَنْ لَا ‏ ‏عَصَبَةَ ‏ ‏لَهُ ‏","","",""],[2820,2820,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏عَنْ رَجُلٍ مَاتَ وَتَرَكَ ابْنَتَهُ لَا يُعْلَمُ لَهُ وَارِثٌ غَيْرُهَا قَالَ ‏ ‏لَهَا الْمَالُ كُلُّهُ ‏","","",""],[2821,2821,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏كَانَ ‏ ‏لَا ‏ ‏يَرُدُّ ‏ ‏عَلَى أَخٍ لِأُمٍّ مَعَ أُمٍّ وَلَا عَلَى جَدَّةٍ إِذَا كَانَ مَعَهَا غَيْرُهَا مَنْ لَهُ ‏ ‏فَرِيضَةٌ ‏ ‏وَلَا عَلَى ابْنَةِ ابْنٍ مَعَ ابْنَةِ الصُّلْبِ وَلَا عَلَى امْرَأَةٍ وَزَوْجٍ ‏ ‏وَكَانَ ‏ ‏عَلِيٌّ ‏ ‏يَرُدُّ ‏ ‏عَلَى كُلِّ ذِي سَهْمٍ إِلَّا الْمَرْأَةَ وَالزَّوْجَ ‏","","",""],[2822,2822,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ سَالِمٍ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏أُتِيَ فِي ابْنَةٍ أَوْ أُخْتٍ فَأَعْطَاهَا النِّصْفَ وَجَعَلَ مَا بَقِيَ فِي بَيْتِ الْمَالِ ‏ ‏و قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏خَارِجَةَ ‏","","",""],[2823,2823,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏فِي ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏قَالَ ‏ ‏مِيرَاثُهُ لِأُمِّهِ ‏","","",""],[2824,2824,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُعَاذُ بْنُ هَانِئٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏سَأَلَ ‏ ‏عَطَاءَ بْنَ أَبِي رَبَاحٍ ‏ ‏عَنْ وَلَدِ ‏ ‏الْمُتَلَاعِنَيْنِ ‏ ‏لِمَنْ مِيرَاثُهُ قَالَ ‏ ‏لِأُمِّهِ وَأَهْلِهَا ‏","","",""],[2825,2825,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏فِي ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏تَرَكَ أَخَاهُ لِأُمِّهِ وَأُمَّهُ لِأَخِيهِ السُّدُسُ وَلِأُمِّهِ الثُّلُثُ ثُمَّ ‏ ‏يُرَدُّ ‏ ‏عَلَيْهِمْ فَيَصِيرُ لِلْأَخِ الثُّلُثُ وَلِلْأُمِّ الثُّلُثَانِ ‏ ‏و قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏لِأَخِيهِ السُّدُسُ وَمَا بَقِيَ فَلِلْأُمِّ ‏","","",""],[2826,2826,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏أَبِي سَهْلٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏تَرَكَ ابْنَ أَخٍ وَجَدًّا قَالَ ‏ ‏الْمَالُ لِابْنِ الْأَخِ ‏","","",""],[2827,2827,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏سَالِمُ بْنُ نُوحٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏فِي مِيرَاثِ ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏لِأُمِّهِ الثُّلُثُ وَالثُّلُثَانِ لِبَيْتِ الْمَالِ ‏","","",""],[2828,2828,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏سَالِمُ بْنُ نُوحٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مِيرَاثُهُ لِأُمِّهِ ‏ ‏تَعْقِلُ ‏ ‏عَنْهُ ‏ ‏عَصَبَةُ ‏ ‏أُمِّهِ ‏ ‏و قَالَ ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏لِأُمِّهِ الثُّلُثُ وَبَقِيَّةُ الْمَالِ ‏ ‏لِعَصَبَةِ ‏ ‏أُمِّهِ ‏","","",""],[2829,2829,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏وَابْنَ مَسْعُودٍ ‏ ‏قَالَا ‏ ‏فِي وَلَدِ ‏ ‏مُلَاعَنَةٍ ‏ ‏تَرَكَ جَدَّتَهُ وَإِخْوَتَهُ لِأُمِّهِ قَالَ ‏ ‏لِلْجَدَّةِ الثُّلُثُ وَلِلْإِخْوَةِ الثُّلُثَانِ ‏ ‏و قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏لِلْجَدَّةِ السُّدُسُ وَلِلْإِخْوَةِ لِلْأُمِّ الثُّلُثُ وَمَا بَقِيَ فَلِبَيْتِ الْمَالِ ‏","","",""],[2830,2830,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏وَحُمَيدٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏تَرِثُهُ أُمُّهُ ‏ ‏يَعْنِي ابْنَ ‏ ‏الْمُلَاعَنَةِ ‏","","",""],[2831,2831,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَنَّ ‏ ‏النَّخَعِيَّ ‏ ‏وَالشَّعْبِيَّ ‏ ‏قَالَا ‏ ‏تَرِثُهُ أُمُّهُ ‏","","",""],[2832,2832,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏قَالَ ‏ ‏كَتَبْتُ إِلَى ‏ ‏أَخٍ لِي ‏ ‏مِنْ ‏ ‏بَنِي زُرَيْقٍ ‏ ‏أَسْأَلُهُ لِمَنْ قَضَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏فَكَتَبَ إِلَيَّ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِهِ لِأُمِّهِ هِيَ بِمَنْزِلَةِ أُمِّهِ وَأَبِيهِ ‏ ‏و قَالَ ‏ ‏سُفْيَانُ ‏ ‏الْمَالُ كُلُّهُ لِلْأُمِّ هِيَ بِمَنْزِلَةِ أَبِيهِ وَأُمِّهِ ‏","","",""],[2833,2833,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏تَرَكَ أُمَّهُ ‏ ‏وَعَصَبَةَ ‏ ‏أُمِّهِ قَالَ ‏ ‏الثُّلُثُ لِأُمِّهِ وَمَا بَقِيَ ‏ ‏فَلِعَصَبَةِ ‏ ‏أُمِّهِ ‏","","",""],[2834,2834,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَعَبْدِ اللَّهِ ‏ ‏فِي ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏قَالَا ‏ ‏عَصَبَتُهُ ‏ ‏عَصَبَةُ أُمِّهِ ‏","","",""],[2835,2835,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ الْحَلَبِيُّ مُوسَى بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏مِيرَاثُ وَلَدِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏لِأُمِّهِ قُلْتُ فَإِنْ كَانَ لَهُ أَخٌ مِنْ أُمِّهِ قَالَ لَهُ السُّدُسُ ‏","","",""],[2836,2836,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏قَالَ ‏ ‏وَلَدُ ‏ ‏الْمُلَاعَنَةِ ‏ ‏لِأُمِّهِ تَرِثُ ‏ ‏فَرِيضَتَهَا ‏ ‏مِنْهُ وَسَائِرُ ذَلِكَ فِي بَيْتِ الْمَالِ ‏","","",""],[2837,2837,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏تَلَاعَنَا ‏ ‏فُرِّقَ بَيْنَهُمَا وَلَمْ يَجْتَمِعَا وَدُعِيَ الْوَلَدُ لِأُمِّهِ يُقَالُ ابْنُ فُلَانَةَ هِيَ ‏ ‏عَصَبَتُهُ ‏ ‏يَرِثُهَا وَتَرِثُهُ وَمَنْ دَعَاهُ لِزِنْيَةٍ جُلِدَ ‏","","",""],[2838,2838,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هَانِئٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي وَلَدِ ‏ ‏الْمُتَلَاعِنَيْنِ ‏ ‏أَنَّهُ ‏ ‏تَرِثُهُ ‏ ‏عَصَبَةُ ‏ ‏أُمِّهِ وَهُمْ ‏ ‏يَعْقِلُونَ ‏ ‏عَنْهُ ‏","","",""],[2839,2839,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَزْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي وَلَدِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏هُوَ الَّذِي لَا ‏ ‏أَبَ لَهُ تَرِثُهُ أُمُّهُ وَإِخْوَتُهُ مِنْ أُمِّهِ ‏ ‏وَعَصَبَةُ ‏ ‏أُمِّهِ فَإِنْ قَذَفَهُ قَاذِفٌ جُلِدَ قَاذِفُهُ ‏","","",""],[2840,2840,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏أَنَّهُ سُئِلَ عَنْ مِيرَاثِ وَلَدِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏لِمَنْ هُوَ قَالَ ‏ ‏جَعَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأُمِّهِ فِي سَبَبِهِ لِمَا لَقِيَتْ مِنْ الْبَلَاءِ وَلِإِخْوَتِهِ مِنْ أُمِّهِ ‏ ‏و قَالَ ‏ ‏مَكْحُولٌ ‏ ‏فَإِنْ مَاتَتْ الْأُمُّ وَتَرَكَتْ ابْنَهَا ثُمَّ تُوُفِّيَ ابْنُهَا الَّذِي جُعِلَ لَهَا كَانَ مِيرَاثُهُ لِإِخْوَتِهِ مِنْ أُمِّهِ كُلُّهُ لِأَنَّهُ كَانَ لِأُمِّهِمْ وَجَدِّهِمْ وَكَانَ لِأَبِيهَا السُّدُسُ مِنْ ابْنِ ابْنَتِهِ وَلَيْسَ يَرِثُ الْجَدُّ إِلَّا فِي هَذِهِ الْمَنْزِلَةِ لِأَنَّهُ إِنَّمَا هُوَ ‏ ‏أَبُ الْأُمِّ وَإِنَّمَا وَرِثَ الْإِخْوَةُ مِنْ الْأُمِّ أُمَّهُمْ وَوَرِثَ الْجَدُّ ابْنَتَهُ لِأَنَّهُ جُعِلَ لَهَا فَالْمَالُ الَّذِي لِلْوَلَدِ لِوَرَثَةِ الْأُمِّ وَهُوَ يُحْرِزُهُ الْجَدُّ وَحْدَهُ إِذَا لَمْ يَكُنْ غَيْرُهُ ‏","","",""],[2841,2841,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ قَوْمًا اخْتَصَمُوا إِلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي وَلَدِ ‏ ‏الْمُتَلَاعِنَيْنِ ‏ ‏فَجَاءَ ‏ ‏عَصَبَةُ ‏ ‏أَبِيهِ يَطْلُبُونَ مِيرَاثَهُ فَقَالَ ‏ ‏إِنَّ أَبَاهُ كَانَ تَبَرَّأَ مِنْهُ فَلَيْسَ لَكُمْ مِنْ مِيرَاثِهِ شَيْءٌ فَقَضَى بِمِيرَاثِهِ لِأُمِّهِ وَجَعَلَهَا ‏ ‏عَصَبَتَهُ ‏","","",""],[2842,2842,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مُحَمَّدَ بْنَ عَلِيٍّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَلِيٍّ ‏ ‏فِي الرَّجُلِ يَكُونُ لَهُ مَا لِلرَّجُلِ وَمَا لِلْمَرْأَةِ مِنْ أَيِّهِمَا يُوَرَّثُ فَقَالَ ‏ ‏مِنْ أَيِّهِمَا بَالَ ‏","","",""],[2843,2843,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏شِبَاكٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏فِي ‏ ‏الْخُنْثَى ‏ ‏قَالَ ‏ ‏يُوَرَّثُ مِنْ قِبَلِ ‏ ‏مَبَالِهِ ‏","","",""],[2844,2844,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هَانِئٍ ‏ ‏قَالَ سُئِلَ ‏ ‏عَامِرٌ ‏ ‏عَنْ مَوْلُودٍ وُلِدَ وَلَيْسَ بِذَكَرٍ وَلَا أُنْثَى لَيْسَ لَهُ مَا لِلذَّكَرِ وَلَيْسَ لَهُ مَا لِلْأُنْثَى يُخْرِجُ مِنْ سُرَّتِهِ كَهَيْئَةِ الْبَوْلِ وَالْغَائِطِ سُئِلَ عَنْ مِيرَاثِهِ فَقَالَ ‏ ‏نِصْفُ حَظِّ الذَّكَرِ وَنِصْفُ حَظِّ الْأُنْثَى ‏","","",""],[2845,2845,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏الْكَلَالَةِ ‏ ‏فَقَالَ ‏ ‏إِنِّي سَأَقُولُ فِيهَا بِرَأْيِي فَإِنْ كَانَ صَوَابًا فَمِنْ اللَّهِ وَإِنْ كَانَ خَطَأً فَمِنِّي وَمِنْ الشَّيْطَانِ أُرَاهُ مَا خَلَا الْوَالِدَ وَالْوَلَدَ فَلَمَّا اسْتُخْلِفَ ‏ ‏عُمَرُ ‏ ‏قَالَ إِنِّي ‏ ‏لَأَسْتَحْيِي اللَّهَ أَنْ أَرُدَّ شَيْئًا قَالَهُ ‏ ‏أَبُو بَكْرٍ ‏","","",""],[2846,2846,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ هُوَ ابْنُ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا ‏ ‏أَعْضَلَ ‏ ‏بِأَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْءٌ مَا ‏ ‏أَعْضَلَتْ ‏ ‏بِهِمْ ‏ ‏الْكَلَالَةُ ‏","","",""],[2847,2847,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏الْكَلَالَةُ ‏ ‏مَا خَلَا الْوَالِدَ وَالْوَلَدَ ‏","","",""],[2848,2848,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَقْرَأُ هَذِهِ الْآيَةَ ‏ { ‏وَإِنْ كَانَ رَجُلٌ يُورَثُ ‏ ‏كَلَالَةً ‏ ‏أَوْ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ ‏} ‏لِأُمٍّ ‏","","",""],[2849,2849,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏أَنَّ ‏ ‏عَاصِمَ بْنَ عُمَرَ بْنِ قَتَادَةَ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏الْتَمَسَ مَنْ يَرِثُ ‏ ‏ابْنَ الدَّحْدَاحَةِ ‏ ‏فَلَمْ يَجِدْ وَارِثًا فَدَفَعَ مَالَ ‏ ‏ابْنِ الدَّحْدَاحَةِ ‏ ‏إِلَى أَخْوَالِ ‏ ‏ابْنِ الدَّحْدَاحَةِ ‏","","",""],[2850,2850,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اللَّهُ وَرَسُولُهُ مَوْلَى مَنْ لَا مَوْلَى لَهُ وَالْخَالُ وَارِثُ مَنْ لَا وَارِثَ لَهُ ‏","","",""],[2851,2851,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏زِيَادٍ ‏ ‏قَالَ ‏ ‏أُتِيَ ‏ ‏عُمَرُ ‏ ‏فِي عَمٍّ لِأُمٍّ وَخَالَةٍ فَأَعْطَى الْعَمَّ لِلْأُمِّ الثُّلُثَيْنِ وَأَعْطَى الْخَالَةَ الثُّلُثَ ‏","","",""],[2852,2852,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَعْطَى الْخَالَةَ الثُّلُثَ وَالْعَمَّةَ الثُّلُثَيْنِ ‏","","",""],[2853,2853,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏غَالِبِ بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ حَبْتَرٍ النَّهْشَلِيِّ ‏ ‏قَالَ أُتِيَ ‏ ‏عَبْدُ الْمَلِكِ بْنُ مَرْوَانَ ‏ ‏فِي خَالَةٍ وَعَمَّةٍ فَقَامَ ‏ ‏شَيْخٌ ‏ ‏فَقَالَ ‏ ‏شَهِدْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَعْطَى الْخَالَةَ الثُّلُثَ وَالْعَمَّةَ الثُّلُثَيْنِ قَالَ فَهَمَّ أَنْ يَكْتُبَ بِهِ ثُمَّ قَالَ أَيْنَ ‏ ‏زَيْدٌ ‏ ‏عَنْ هَذَا ‏","","",""],[2854,2854,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏الْخَالَةُ بِمَنْزِلَةِ الْأُمِّ وَالْعَمَّةُ بِمَنْزِلَةِ الْأَبِ وَبِنْتُ الْأَخِ بِمَنْزِلَةِ الْأَخِ وَكُلُّ رَحِمٍ بِمَنْزِلَةِ رَحِمِهِ الَّتِي ‏ ‏يُدْلِي ‏ ‏بِهَا إِذَا لَمْ يَكُنْ وَارِثٌ ذُو قَرَابَةٍ ‏","","",""],[2855,2855,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ قَيْسٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَضَى فِي أَهْلِ طَاعُونِ ‏ ‏عَمَوَاسَ ‏ ‏أَنَّهُمْ كَانُوا إِذَا كَانُوا مِنْ قِبَلِ الْأَبِ سَوَاءً فَبَنُو الْأُمِّ أَحَقُّ وَإِذَا كَانَ بَعْضُهُمْ أَقْرَبَ مِنْ بَعْضٍ بِأَبٍ فَهُمْ أَحَقُّ بِالْمَالِ ‏","","",""],[2856,2856,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو إِسْحَقَ الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادِ بْنِ الْهَادِ ‏ ‏قَالَ ‏ ‏أُصِيبَ ‏ ‏سَالِمٌ ‏ ‏مَوْلَى ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏يَوْمَ ‏ ‏الْيَمَامَةِ ‏ ‏فَبَلَغَ مِيرَاثُهُ مِائَتَيْ دِرْهَمٍ فَقَالَ ‏ ‏عُمَرُ ‏ ‏احْبِسُوهَا عَلَى أُمِّهِ حَتَّى تَأْتِيَ عَلَى آخِرِهَا ‏","","",""],[2857,2857,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِخْوَةُ مِنْ الْأُمِّ يَتَوَارَثُونَ دُونَ ‏ ‏بَنِي الْعَلَّاتِ ‏ ‏يَرِثُ الرَّجُلُ أَخَاهُ لِأَبِيهِ وَأُمِّهِ دُونَ أَخِيهِ لِأَبِيهِ ‏","","",""],[2858,2858,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَرَأَيْتَ رَجُلًا تَرَكَ ابْنَ ابْنَتِهِ أَيَرِثُهُ قَالَ لَا ‏","","",""],[2859,2859,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏الْأُمُّ ‏ ‏عَصَبَةُ ‏ ‏مَنْ لَا ‏ ‏عَصَبَةَ ‏ ‏لَهُ وَالْأُخْتُ ‏ ‏عَصَبَةُ ‏ ‏مَنْ لَا ‏ ‏عَصَبَةَ ‏ ‏لَهُ ‏","","",""],[2860,2860,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلْحِقُوا ‏ ‏الْفَرَائِضَ ‏ ‏بِأَهْلِهَا فَمَا بَقِيَ فَهُوَ لِأَوْلَى رَجُلٍ ذَكَرٍ ‏","","",""],[2861,2861,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏مُحَمَّدِ بْنِ الْأَشْعَثِ ‏ ‏أَنَّ عَمَّةً لَهُ تُوُفِّيَتْ يَهُودِيَّةً ‏ ‏بِالْيَمَنِ ‏ ‏فَذَكَرَ ذَلِكَ ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏فَقَالَ ‏ ‏يَرِثُهَا أَقْرَبُ النَّاسِ إِلَيْهَا مِنْ أَهْلِ دِينِهَا ‏","","",""],[2862,2862,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏مَاتَتْ عَمَّةُ ‏ ‏الْأَشْعَثِ بْنِ قَيْسٍ ‏ ‏وَهِيَ يَهُودِيَّةٌ فَأَتَى ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏فَقَالَ ‏ ‏أَهْلُ دِينِهَا يَرِثُونَهَا ‏","","",""],[2863,2863,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏أَهْلُ الشِّرْكِ لَا نَرِثُهُمْ وَلَا يَرِثُونَا ‏","","",""],[2864,2864,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏عِيسَى الْحَنَّاطِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏قَالُوا ‏ ‏لَا يَتَوَارَثُ أَهْلُ دِينَيْنِ ‏","","",""],[2865,2865,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏لَا يَتَوَارَثُ أَهْلُ مِلَّتَيْنِ ‏","","",""],[2866,2866,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏لَا نَرِثُ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏وَلَا يَرِثُونَا إِلَّا أَنْ يَمُوتَ لِلرَّجُلِ عَبْدُهُ أَوْ أَمَتُهُ ‏","","",""],[2867,2867,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَرِثُ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏وَلَا يَرِثُونَا إِلَّا الرَّجُلُ يَرِثُ عَبْدَهُ أَوْ أَمَتَهُ ‏","","",""],[2868,2868,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏يُوَرِّثُ الْمُسْلِمَ مِنْ الْكَافِرِ وَلَا يُوَرِّثُ الْكَافِرَ مِنْ الْمُسْلِمِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏مَسْرُوقٌ ‏ ‏وَمَا حَدَثَ فِي الْإِسْلَامِ قَضَاءٌ أَحَبُّ إِلَيَّ مِنْهُ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏تَقُولُ بِهَذَا ‏ ‏قَالَ ‏ ‏لَا ‏","","",""],[2869,2869,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏أَنَّ ‏ ‏الْمُعْزِلَةَ بِنْتَ الْحَارِثِ ‏ ‏تُوُفِّيَتْ ‏ ‏بِالْيَمَنِ ‏ ‏وَهِيَ يَهُودِيَّةٌ فَرَكِبَ ‏ ‏الْأَشْعَثُ بْنُ قَيْسٍ ‏ ‏وَكَانَتْ عَمَّتَهُ إِلَى ‏ ‏عُمَرَ ‏ ‏فِي مِيرَاثِهَا ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏لَيْسَ ذَاكَ لَكَ ‏ ‏يَرِثُهَا أَقْرَبُ النَّاسِ مِنْهَا مِنْ أَهْلِ دِينِهَا لَا يَتَوَارَثُ مِلَّتَانِ ‏","","",""],[2870,2870,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏لَا يَتَوَارَثُ مِلَّتَانِ شَتَّى وَلَا ‏ ‏يَحْجُبُ ‏ ‏مَنْ لَا يَرِثُ ‏","","",""],[2871,2871,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَرِثُ الْمُسْلِمُ الْكَافِرَ وَلَا الْكَافِرُ الْمُسْلِمَ ‏","","",""],[2872,2872,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِذَا مَاتَ الْمَيِّتُ وَجَبَتْ الْحُقُوقُ لِأَهْلِهَا وَلَمْ يَجْعَلْ لِمَنْ أَسْلَمَ أَوْ أُعْتِقَ قَبْلَ أَنْ يُقْسَمَ الْمِيرَاثُ شَيْئًا ‏","","",""],[2873,2873,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَرِثُ الْمُسْلِمُ الْكَافِرَ وَلَا الْكَافِرُ الْمُسْلِمَ ‏","","",""],[2874,2874,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَرِثُ الْمُسْلِمُ الْكَافِرَ وَلَا الْكَافِرُ الْمُسْلِمَ ‏","","",""],[2875,2875,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لَيْسَ ‏ ‏لِلْمُكَاتَبِ ‏ ‏مِيرَاثٌ مَا بَقِيَ عَلَيْهِ شَيْءٌ مِنْ ‏ ‏مُكَاتَبَتِهِ ‏","","",""],[2876,2876,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي رَجُلٍ لَهُ بَنُونَ قَدْ أَعْتَقَ مِنْ بَعْضِهِمْ النِّصْفَ وَمِنْ بَعْضِهِمْ الثُّلُثَ وَمِنْ بَعْضٍ الرُّبُعَ قَالَ ‏ ‏لَا يَرِثُونَ حَتَّى يُعْتَقُوا ‏","","",""],[2877,2877,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ الرَّقِّيُّ ‏ ‏وَسَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي رَجُلٍ اشْتَرَى ابْنَهُ فِي مَرَضِهِ قَالَ ‏ ‏إِنْ خَرَجَ مِنْ الثُّلُثِ وَرِثَهُ وَإِنْ وَقَعَتْ عَلَيْهِ ‏ ‏السِّعَايَةُ ‏ ‏لَمْ يَرِثْ ‏","","",""],[2878,2878,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏حَدُّ ‏ ‏الْمُكَاتَبِ ‏ ‏حَدُّ الْمَمْلُوكِ حَتَّى يُعْتَقَ ‏","","",""],[2879,2879,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَوْلَى ‏ ‏أَخٌ فِي الدِّينِ وَنِعْمَةٌ أَحَقُّ النَّاسِ بِمِيرَاثِهِ أَقْرَبُهُمْ مِنْ الْمُعْتِقِ ‏","","",""],[2880,2880,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَمُحَمَّدُ بْنُ سَالِمٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي رَجُلٍ أَعْتَقَ مَمْلُوكًا ثُمَّ مَاتَ ‏ ‏الْمَوْلَى ‏ ‏وَالْمَمْلُوكُ وَتَرَكَ الْمُعْتِقُ أَبَاهُ وَابْنَهُ قَالَا ‏ ‏الْمَالُ ‏ ‏لِلِابْنِ ‏","","",""],[2881,2881,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏فِي رَجُلٍ تَرَكَ أَبَاهُ وَابْنَ ابْنِهِ فَقَالَ ‏ ‏الْوَلَاءُ ‏ ‏لِابْنِ ‏ ‏الِابْنِ ‏","","",""],[2882,2882,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مُعَمَّرٌ ‏ ‏حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي مَرْيَمَ ‏ ‏أَنَّ امْرَأَةً أَعْتَقَتْ عَبْدًا لَهَا ثُمَّ تُوُفِّيَتْ وَتَرَكَتْ ابْنَهَا وَأَخَاهَا ثُمَّ تُوُفِّيَ ‏ ‏مَوْلَاهَا ‏ ‏فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ الْمَرْأَةِ وَأَخُوهَا فِي مِيرَاثِهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِيرَاثُهُ لِابْنِ الْمَرْأَةِ فَقَالَ أَخُوهَا يَا رَسُولَ اللَّهِ لَوْ أَنَّهُ جَرَّ ‏ ‏جَرِيرَةً ‏ ‏عَلَى مَنْ كَانَتْ قَالَ عَلَيْكَ ‏","","",""],[2883,2883,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّلْتِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ رَجُلٍ أَعْتَقَ مَمْلُوكًا لَهُ فَمَاتَ وَمَاتَ ‏ ‏الْمَوْلَى ‏ ‏فَتَرَكَ الْمُعْتِقُ أَبَاهُ وَابْنَهُ فَقَالَ ‏ ‏لِأَبِيهِ كَذَا وَمَا بَقِيَ فَلِابْنِهِ ‏","","",""],[2884,2884,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّلْتِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَكَمَ ‏ ‏وَحَمَّادًا ‏ ‏يَقُولَانِ ‏ ‏هُوَ ‏ ‏لِلِابْنِ ‏","","",""],[2885,2885,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَشْعَثُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَرَأَى رَجُلًا يُبَاعُ فَأَتَاهُ فَسَاوَمَ بِهِ ثُمَّ تَرَكَهُ فَرَآهُ رَجُلٌ فَاشْتَرَاهُ فَأَعْتَقَهُ ثُمَّ جَاءَ بِهِ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي اشْتَرَيْتُ هَذَا فَأَعْتَقْتُهُ فَمَا ‏ ‏تَرَى فِيهِ فَقَالَ ‏ ‏هُوَ أَخُوكَ ‏ ‏وَمَوْلَاكَ ‏ ‏قَالَ مَا ‏ ‏تَرَى فِي صُحْبَتِهِ فَقَالَ إِنْ شَكَرَكَ فَهُوَ خَيْرٌ لَهُ وَشَرٌّ لَكَ وَإِنْ كَفَرَكَ فَهُوَ خَيْرٌ لَكَ وَشَرٌّ لَهُ قَالَ مَا ‏ ‏تَرَى فِي مَالِهِ قَالَ إِنْ مَاتَ وَلَمْ يَتْرُكْ ‏ ‏عَصَبَةً ‏ ‏فَأَنْتَ وَارِثُهُ ‏","","",""],[2886,2886,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏وَسَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏أَنَّ ابْنَةَ ‏ ‏حَمْزَةَ ‏ ‏أَعْتَقَتْ عَبْدًا لَهَا فَمَاتَ وَتَرَكَ ابْنَتَهُ ‏ ‏وَمَوْلَاتَهُ ‏ ‏بِنْتَ ‏ ‏حَمْزَةَ ‏ ‏فَقَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِيرَاثَهُ بَيْنَ ابْنَتِهِ وَمَوْلَاتِهِ بِنْتِ ‏ ‏حَمْزَةَ ‏ ‏نِصْفَيْنِ ‏","","",""],[2887,2887,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏شَمُوسَ الْكِنْدِيَّةِ ‏ ‏قَالَتْ ‏ ‏قَاضَيْتُ إِلَى ‏ ‏عَلِيٍّ ‏ ‏فِي أَبٍ مَاتَ فَلَمْ يَدَعْ أَحَدًا غَيْرِي ‏ ‏وَمَوْلَاهُ ‏ ‏فَأَعْطَانِي النِّصْفَ وَأَعْطَى ‏ ‏مَوْلَاهُ ‏ ‏النِّصْفَ ‏","","",""],[2888,2888,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي الْكَنُودِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّهُ ‏ ‏أُتِيَ بِابْنَةٍ ‏ ‏وَمَوْلًى ‏ ‏فَأَعْطَى ‏ ‏الِابْنَةَ النِّصْفَ ‏ ‏وَالْمَوْلَى ‏ ‏النِّصْفَ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏فَمَنْزِلِي هَذَا نَصِيبُ ‏ ‏الْمَوْلَى ‏ ‏الَّذِي وَرِثَهُ عَنْ ‏ ‏مَوْلَاهُ ‏","","",""],[2889,2889,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏ابْنِ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُدْلِجٍ ‏ ‏أَنَّهُ مَاتَ وَتَرَكَ ابْنَتَهُ ‏ ‏وَمَوَالِيَهُ ‏ ‏فَأَعْطَى ‏ ‏عَلِيٌّ ‏ ‏ابْنَتَهُ النِّصْفَ ‏ ‏وَمَوَالِيَهُ ‏ ‏النِّصْفَ ‏","","",""],[2890,2890,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏ابْنِ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏الشَّمُّوسِ ‏ ‏أَنَّ أَبَاهَا مَاتَ فَجَعَلَ ‏ ‏عَلِيٌّ ‏ ‏لَهَا ‏ ‏النِّصْفَ ‏ ‏وَلِمَوَالِيهِ ‏ ‏النِّصْفَ ‏","","",""],[2891,2891,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنْ ‏ ‏جَهْمِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏أَنَّهُ سُئِلَ عَنْ أُخْتَيْنِ اشْتَرَتْ إِحْدَاهُمَا أَبَاهَا فَأَعْتَقَتْهُ ثُمَّ مَاتَ قَالَ ‏ ‏لَهُمَا الثُّلُثَانِ ‏ ‏فَرِيضَتُهُمَا ‏ ‏فِي كِتَابِ اللَّهِ وَمَا بَقِيَ فَلِلْمُعْتِقَةِ دُونَ الْأُخْرَى ‏","","",""],[2892,2892,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْعَثُ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي امْرَأَةٍ أَعْتَقَتْ أَبَاهَا فَمَاتَ الْأَبُ وَتَرَكَ أَرْبَعَ بَنَاتٍ هِيَ إِحْدَاهُنَّ قَالَ ‏ ‏لَيْسَ عَلَيْهِ ‏ ‏مِنَّةٌ ‏ ‏لَهُنَّ الثُّلُثَانِ وَهِيَ مَعَهُنَّ ‏","","",""],[2893,2893,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏حَيَّانَ بْنِ سَلْمَانَ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏سُوَيْدِ بْنِ غَفَلَةَ ‏ ‏فَجَاءَهُ رَجُلٌ فَسَأَلَهُ عَنْ ‏ ‏فَرِيضَةِ ‏ ‏رَجُلٍ تَرَكَ ابْنَتَهُ وَامْرَأَتَهُ قَالَ أَنَا أُنْبِئُكَ قَضَاءَ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏حَسْبِي ‏ ‏قَضَاءُ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَضَى ‏ ‏عَلِيٌّ ‏ ‏لِامْرَأَتِهِ الثُّمُنَ وَلِابْنَتِهِ النِّصْفَ ثُمَّ رَدَّ الْبَقِيَّةَ عَلَى ابْنَتِهِ ‏","","",""],[2894,2894,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏أَنَّ ‏ ‏مَوْلَاةً ‏ ‏لِإِبْرَاهِيمَ ‏ ‏تُوُفِّيَتْ وَتَرَكَتْ مَالًا فَقُلْتُ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ لَهَا ذَا قَرَابَةٍ ‏","","",""],[2895,2895,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏وَعَلِيٍّ ‏ ‏وَزَيْدٍ ‏ ‏قَالَ وَأَحْسَبُهُ قَدْ ذَكَرَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏أَيْضًا ‏ ‏أَنَّهُمْ قَالُوا ‏ ‏الْوَلَاءُ ‏ ‏لِلْكُبْرِ ‏ ‏يَعْنُونَ بِالْكُبْرِ مَا كَانَ أَقْرَبَ بِأَبٍ أَوْ أُمٍّ ‏","","",""],[2896,2896,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏كُتِبَ إِلَى ‏ ‏عُمَرَ ‏ ‏فِي شَأْنِ ‏ ‏فُكَيْهَةَ بِنْتِ سَمْعَانَ ‏ ‏أَنَّهَا مَاتَتْ وَتَرَكَتْ ابْنَ أَخِيهَا لِأَبِيهَا وَأُمِّهَا وَابْنَ أَخِيهَا لِأَبِيهَا فَكَتَبَ ‏ ‏عُمَرُ ‏ ‏إِنَّ ‏ ‏الْوَلَاءَ ‏ ‏لِلْكُبْرِ ‏","","",""],[2897,2897,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏وَزَيْدًا ‏ ‏قَالَا ‏ ‏الْوَلَاءُ ‏ ‏لِلْكُبْرِ ‏ ‏و قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَشُرَيْحٌ ‏ ‏لِلْوَرَثَةِ ‏","","",""],[2898,2898,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏قَضَى ‏ ‏عُمَرُ ‏ ‏وَعَبْدُ اللَّهِ ‏ ‏وَعَلِيٌّ ‏ ‏وَزَيْدٌ ‏ ‏لِلْكُبْرِ ‏ ‏بِالْوَلَاءِ ‏","","",""],[2899,2899,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏تُوُفِّيَتْ ‏ ‏فُكَيْهَةُ بِنْتُ سَمْعَانَ ‏ ‏وَتَرَكَتْ ابْنَ أَخِيهَا لِأَبِيهَا وَبَنِي بَنِي أَخِيهَا لِأَبِيهَا وَأُمِّهَا ‏ ‏فَوَرَّثَ ‏ ‏عُمَرُ ‏ ‏بَنِي أَخِيهَا لِأَبِيهَا ‏","","",""],[2900,2900,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏وَعَلِيٍّ ‏ ‏وَزَيْدٍ ‏ ‏أَنَّهُمْ قَالُوا ‏ ‏الْوَلَاءُ ‏ ‏لِلْكُبْرِ ‏","","",""],[2901,2901,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي أَخَوَيْنِ وَرِثَا مَوْلًى كَانَ أَعْتَقَهُ أَبُوهُمَا فَمَاتَ أَحَدُهُمَا وَتَرَكَ وَلَدًا قَالَ ‏ ‏كَانَ ‏ ‏عَلِيٌّ ‏ ‏وَزَيْدٌ ‏ ‏وَعَبْدُ اللَّهِ ‏ ‏يَقُولُونَ ‏ ‏الْوَلَاءُ ‏ ‏لِلْكُبْرِ ‏","","",""],[2902,2902,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَطَرًا الْوَرَّاقَ ‏ ‏يَقُولُ قَالَ ‏ ‏عُمَرُ ‏ ‏وَعَلِيٌّ ‏ ‏الْوَلَاءُ ‏ ‏لِلْكُبْرِ ‏","","",""],[2903,2903,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏عَنْ ‏ ‏رَوْحٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏الْوَلَاءُ لِلْكُبْرِ ‏","","",""],[2904,2904,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْوَلَاءُ ‏ ‏لِلْكُبْرِ ‏","","",""],[2905,2905,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏وَسُفْيَانُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الرَّجُلِ ‏ ‏يُوَالِي ‏ ‏الرَّجُلَ قَالَا ‏ ‏هُوَ بَيْنَ الْمُسْلِمِينَ قَالَ ‏ ‏سُفْيَانُ ‏ ‏وَكَذَلِكَ نَقُولُ ‏","","",""],[2906,2906,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏تَمِيمًا الدَّارِيَّ ‏ ‏يَقُولُ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ مَا السُّنَّةُ فِي الرَّجُلِ مِنْ أَهْلِ الْكُفْرِ يُسْلِمُ عَلَى يَدَيْ رَجُلٍ مِنْ الْمُسْلِمِينَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ أَوْلَى النَّاسِ بِمَحْيَاهُ وَمَمَاتِهِ ‏","","",""],[2907,2907,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏سُئِلَ عَنْ رَجُلٍ مِنْ أَهْلِ ‏ ‏السَّوَادِ ‏ ‏أَسْلَمَ عَلَى يَدَيْ رَجُلٍ قَالَ ‏ ‏يَعْقِلُ ‏ ‏عَنْهُ وَيَرِثُهُ ‏","","",""],[2908,2908,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏تَرِثُ الْمَرْأَةُ مِنْ دِيَةِ زَوْجِهَا فِي الْعَمْدِ وَالْخَطَإِ ‏","","",""],[2909,2909,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الدِّيَةُ عَلَى ‏ ‏فَرَائِضِ ‏ ‏اللَّهِ ‏","","",""],[2910,2910,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ ‏ ‏الدِّيَةُ سَبِيلُهَا سَبِيلُ الْمِيرَاثِ ‏","","",""],[2911,2911,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَدَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏كَتَبَ ‏ ‏أَنْ يُوَرَّثَ الْإِخْوَةُ مِنْ الْأُمِّ مِنْ الدِّيَةِ ‏","","",""],[2912,2912,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏الْعَقْلُ ‏ ‏مِيرَاثٌ بَيْنَ وَرَثَةِ الْقَتِيلِ عَلَى كِتَابِ اللَّهِ ‏ ‏وَفَرَائِضِهِ ‏","","",""],[2913,2913,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏بَعْضِ وَلَدِ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏لَقَدْ ظَلَمَ مَنْ لَمْ يُوَرِّثْ الْإِخْوَةَ مِنْ الْأُمِّ مِنْ الدِّيَةِ ‏","","",""],[2914,2914,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ سَالِمٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏وَعَلِيٍّ ‏ ‏وَزَيْدٍ ‏ ‏قَالُوا ‏ ‏الدِّيَةُ تُورَثُ كَمَا يُورَثُ الْمَالُ خَطَؤُهُ وَعَمْدُهُ ‏","","",""],[2915,2915,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَلِيٌّ ‏ ‏لَا يُوَرِّثُ الْإِخْوَةَ مِنْ الْأُمِّ وَلَا الزَّوْجَ وَلَا الْمَرْأَةَ مِنْ الدِّيَةِ شَيْئًا ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏بَعْضُهُمْ يُدْخِلُ بَيْنَ ‏ ‏إِسْمَعِيلَ ‏ ‏وَعَامِرٍ ‏ ‏رَجُلًا ‏","","",""],[2916,2916,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏زِيَادٍ الْأَعْلَمِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏لَا يُوَرَّثُ الْإِخْوَةُ مِنْ الْأُمِّ مِنْ الدِّيَةِ ‏","","",""],[2917,2917,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏كُلُّ قَوْمٍ مُتَوَارِثِينَ ‏ ‏عَمِيَ ‏ ‏مَوْتُهُمْ فِي هَدْمٍ أَوْ غَرَقٍ فَإِنَّهُمْ لَا يَتَوَارَثُونَ يَرِثُهُمْ الْأَحْيَاءُ ‏","","",""],[2918,2918,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَتِيقٍ ‏ ‏قَالَ قَرَأْتُ فِي بَعْضِ كُتُبِ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏فِي الْقَوْمِ يَقَعُ عَلَيْهِمْ الْبَيْتُ لَا يُدْرَى أَيُّهُمَا مَاتَ قَبْلُ قَالَ ‏ ‏لَا يُوَرَّثُ الْأَمْوَاتُ بَعْضُهُمْ مِنْ بَعْضٍ وَيُوَرَّثُ الْأَحْيَاءُ مِنْ الْأَمْوَاتِ ‏","","",""],[2919,2919,"","","‏ ‏حَدَّثَنَا ‏ ‏نُعَيْمُ بْنُ حَمَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أُمَّ كُلْثُومٍ ‏ ‏وَابْنَهَا ‏ ‏زَيْدًا ‏ ‏مَاتَا فِي يَوْمٍ وَاحِدٍ فَالْتَقَتْ الصَّائِحَتَانِ فِي الطَّرِيقِ ‏ ‏فَلَمْ يَرِثْ كُلُّ وَاحِدٍ مِنْهُمَا مِنْ صَاحِبِهِ وَأَنَّ أَهْلَ ‏ ‏الْحَرَّةِ ‏ ‏لَمْ يَتَوَارَثُوا وَأَنَّ أَهْلَ ‏ ‏صِفِّينَ ‏ ‏لَمْ يَتَوَارَثُوا ‏","","",""],[2920,2920,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّ بَيْتًا ‏ ‏بِالشَّامِ ‏ ‏وَقَعَ عَلَى قَوْمٍ ‏ ‏فَوَرَّثَ ‏ ‏عُمَرُ ‏ ‏بَعْضَهُمْ مِنْ بَعْضٍ ‏","","",""],[2921,2921,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُرَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّهُ ‏ ‏وَرَّثَ أَخَوَيْنِ قُتِلَا ‏ ‏بِصِفِّينَ ‏ ‏أَحَدَهُمَا مِنْ الْآخَرِ ‏","","",""],[2922,2922,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏أَنَّ رَجُلًا هَلَكَ وَتَرَكَ عَمَّتَهُ وَخَالَتَهُ ‏ ‏فَأَعْطَى ‏ ‏عُمَرُ ‏ ‏الْعَمَّةَ نَصِيبَ الْأَخِ وَأَعْطَى الْخَالَةَ نَصِيبَ الْأُخْتِ ‏","","",""],[2923,2923,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَدْلَى ‏ ‏بِرَحِمٍ أُعْطِيَ بِرَحِمِهِ الَّتِي ‏ ‏يُدْلِي ‏ ‏بِهَا ‏","","",""],[2924,2924,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو إِسْحَقَ الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي رَجُلٍ تَرَكَ عَمَّتَهُ وَابْنَةَ أَخِيهِ قَالَ ‏ ‏الْمَالُ لِابْنَةِ أَخِيهِ ‏","","",""],[2925,2925,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَالُ وَارِثٌ ‏","","",""],[2926,2926,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏وَعَبْدَ اللَّهِ ‏ ‏رَأَيَا ‏ ‏أَنْ يُوَرِّثَا خَالًا ‏","","",""],[2927,2927,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي عَمَّةٍ وَبِنْتِ أَخٍ قَالَ ‏ ‏الْمَالُ لِابْنَةِ الْأَخِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏بَعْضِهِمْ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لِلْعَمَّةِ ‏","","",""],[2928,2928,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي بِنْتِ أَخٍ وَعَمَّةٍ قَالَ ‏ ‏أَعْطِي الْمَالَ لِابْنَةِ الْأَخِ ‏","","",""],[2929,2929,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏فِي رَجُلٍ تُوُفِّيَ وَلَيْسَ لَهُ وَارِثٌ إِلَّا ابْنَةُ أَخِيهِ وَخَالُهُ قَالَ ‏ ‏لِلْخَالِ نَصِيبُ أُخْتِهِ وَلِابْنَةِ الْأَخِ نَصِيبُ أَبِيهَا ‏","","",""],[2930,2930,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَسْرُوقٌ ‏ ‏يُنَزِّلُ الْعَمَّةَ بِمَنْزِلَةِ الْأَبِ إِذَا لَمْ يَكُنْ أَبٌ وَالْخَالَةَ بِمَنْزِلَةِ الْأُمِّ إِذَا لَمْ تَكُنْ أُمٌّ ‏","","",""],[2931,2931,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ حَبَّانَ ‏ ‏نَسَبَهُ إِلَى جَدِّهِ ‏ ‏عَنْ ‏ ‏عَمِّهْ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ ‏ ‏ابْنُ الدَّحْدَاحَةِ ‏ ‏وَكَانَ أَتِيًّا وَهُوَ الَّذِي لَا يُعْرَفُ لَهُ أَصْلٌ فَكَانَ فِي ‏ ‏بَنِي الْعَجْلَانِ ‏ ‏وَلَمْ يَتْرُكْ ‏ ‏عَقِبًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعَاصِمِ بْنِ عَدِيٍّ ‏ ‏هَلْ تَعْلَمُونَ لَهُ فِيكُمْ نَسَبًا قَالَ مَا نَعْرِفُهُ يَا رَسُولَ اللَّهِ فَدَعَا ابْنَ أُخْتِهِ فَأَعْطَاهُ مِيرَاثَهُ ‏","","",""],[2932,2932,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏أَنَّهُ أَعْطَى خَالًا الْمَالَ ‏","","",""],[2933,2933,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هَانِئٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏عَامِرٌ ‏ ‏عَنْ امْرَأَةٍ ‏ ‏أَوْ رَجُلٍ ‏ ‏تُوُفِّيَ وَتَرَكَ خَالَةً وَعَمَّةً لَيْسَ لَهُ وَارِثٌ وَلَا رَحِمٌ غَيْرُهُمَا فَقَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏يُنَزِّلُ الْخَالَةَ بِمَنْزِلَةِ أُمِّهِ وَيُنَزِّلُ الْعَمَّةَ بِمَنْزِلَةِ أَخِيهَا ‏","","",""],[2934,2934,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي رَجُلٍ اعْتَرَفَ عِنْدَ مَوْتِهِ بِأَلْفِ دِرْهَمٍ لِرَجُلٍ وَأَقَامَ آخَرُ بَيِّنَةً بِأَلْفِ دِرْهَمٍ وَتَرَكَ الْمَيِّتُ أَلْفَ دِرْهَمٍ فَقَالَ ‏ ‏الْمَالُ بَيْنَهُمَا نِصْفَيْنِ إِلَّا أَنْ يَكُونَ مُفْلِسًا فَلَا يَجُوزُ إِقْرَارُهُ ‏","","",""],[2935,2935,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِشَرِيكٍ ‏ ‏كَيْفَ ذَكَرْتَ فِي الْأَخَوَيْنِ يَدَّعِي أَحَدُهُمَا أَخًا قَالَ ‏ ‏يَدْخُلُ عَلَيْهِ فِي نَصِيبِهِ قُلْتُ مَنْ ذَكَرَهُ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏","","",""],[2936,2936,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مُحَمَّدٍ الْمُحَارِبِيُّ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْإِخْوَةِ يَدَّعِي بَعْضُهُمْ الْأَخَ وَيُنْكِرُ الْآخَرُونَ قَالَ ‏ ‏يَدْخُلُ مَعَهُمْ بِمَنْزِلَةِ عَبْدٍ يَكُونُ بَيْنَ الْإِخْوَةِ فَيَعْتِقَ أَحَدُهُمْ نَصِيبَهُ قَالَ وَكَانَ ‏ ‏عَامِرٌ ‏ ‏وَالْحَكَمُ ‏ ‏وَأَصْحَابُهُمَا ‏ ‏يَقُولُونَ ‏ ‏لَا يَدْخُلُ إِلَّا فِي نَصِيبِ الَّذِي اعْتَرَفَ بِهِ ‏","","",""],[2937,2937,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏وَكِيعٍ ‏ ‏قَالَ ‏ ‏إِذَا كَانَا أَخَوَيْنِ فَادَّعَى أَحَدُهُمَا أَخًا وَأَنْكَرَهُ الْآخَرُ ‏ ‏قَالَ كَانَ ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏يَقُولُ ‏ ‏هِيَ مِنْ سِتَّةٍ لِلَّذِي لَمْ يَدَّعِ ثَلَاثَةٌ وَلِلْمُدَّعِي سَهْمَانِ وَلِلْمُدَّعَى سَهْمٌ ‏","","",""],[2938,2938,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏فِي الرَّجُلِ يَكُونُ لَهُ ثَلَاثَةُ بَنِينَ فَقَالَ ثُلُثِي لِأَصْغَرِ بَنِيَّ فَقَالَ الْأَوْسَطُ أَنَا أُجِيزُ وَقَالَ الْأَكْبَرُ لَا أُجِيزُ قَالَ ‏ ‏هِيَ مِنْ تِسْعَةٍ يُخْرِجُ ثُلُثَهُ فَلَهُ سَهْمُهُ وَسَهْمُ الَّذِي أَجَازَ ‏ ‏وَقَالَ ‏ ‏حَمَّادٌ ‏ ‏يَرُدُّ ‏ ‏السَّهْمَ عَلَيْهِمْ جَمِيعًا ‏ ‏وَقَالَ ‏ ‏عَامِرٌ ‏ ‏الَّذِي رَدَّ إِنَّمَا رَدَّ عَلَى نَفْسِهِ ‏","","",""],[2939,2939,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏شُرَيْحٍ ‏ ‏فِي رَجُلٍ أَقَرَّ بِأَخٍ قَالَ ‏ ‏بَيِّنَتُهُ أَنَّهُ أَخُوهُ ‏","","",""],[2940,2940,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ الْعُكْلِيِّ ‏ ‏فِي رَجُلٍ أَقَرَّ عِنْدَ مَوْتِهِ بِأَلْفِ دِرْهَمٍ ‏ ‏مُضَارَبَةً ‏ ‏وَأَلْفٍ دَيْنًا وَلَمْ يَدَعْ إِلَّا أَلْفَ دِرْهَمٍ قَالَ ‏ ‏يُبْدَأُ بِالدَّيْنِ فَإِنْ فَضَلَ فَضْلٌ كَانَ لِصَاحِبِ ‏ ‏الْمُضَارَبَةِ ‏","","",""],[2941,2941,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي رَجُلٍ مَاتَ وَتَرَكَ ثَلَاثَ مِائَةِ دِرْهَمٍ وَثَلَاثَةَ بَنِينَ فَجَاءَ رَجُلٌ يَدَّعِي مِائَةَ دِرْهَمٍ عَلَى الْمَيِّتِ فَأَقَرَّ لَهُ أَحَدُهُمْ قَالَ يَدْخُلُ عَلَيْهِمْ بِالْحِصَّةِ ثُمَّ ‏ ‏قَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏مَا أُرَى أَنْ يَكُونَ مِيرَاثًا حَتَّى ‏ ‏يُقْضَى الدَّيْنُ ‏","","",""],[2942,2942,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَيْثَمَةَ مُصْعَبُ بْنُ سَعِيدٍ الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي رَجُلٍ هَلَكَ وَتَرَكَ ابْنَيْنِ وَتَرَكَ أَلْفَيْ دِرْهَمٍ فَاقْتَسَمَا ‏ ‏الْأَلْفَيْ دِرْهَمٍ وَغَابَ أَحَدُ ‏ ‏الِابْنَيْنِ فَجَاءَ رَجُلٌ فَاسْتَحَقَّ عَلَى الْمَيِّتِ أَلْفَ دِرْهَمٍ قَالَ ‏ ‏يَأْخُذُ جَمِيعَ مَا فِي يَدِ هَذَا الشَّاهِدِ وَيُقَالُ لَهُ اتَّبِعْ أَخَاكَ الْغَائِبَ وَخُذْ نِصْفَ مَا فِي يَدِهِ ‏","","",""],[2943,2943,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏زِيَادٍ الْأَعْلَمِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا أَقَرَّ بَعْضُ الْوَرَثَةِ بِدَيْنٍ فَهُوَ عَلَيْهِ بِحِصَّتِهِ ‏","","",""],[2944,2944,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِذَا شَهِدَ اثْنَانِ مِنْ الْوَرَثَةِ بِدَيْنٍ فَهُوَ مِنْ جَمِيعِ الْمَالِ إِذَا كَانُوا عُدُولًا ‏ ‏وَقَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏عَلَيْهِمَا فِي نَصِيبِهِمَا ‏","","",""],[2945,2945,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ الْوَلِيدِ بْنِ جُمَيْعٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏يُوَرِّثُ أَهْلَ الْمُرْتَدِّ إِذَا قُتِلَ ‏","","",""],[2946,2946,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏أَنَّ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏جَعَلَ مِيرَاثَ الْمُرْتَدِّ لِوَرَثَتِهِ مِنْ الْمُسْلِمِينَ ‏","","",""],[2947,2947,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏قَضَى فِي مِيرَاثِ الْمُرْتَدِّ لِأَهْلِهِ مِنْ الْمُسْلِمِينَ ‏","","",""],[2948,2948,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ هُوَ ابْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ ‏ ‏إِذَا قَتَلَ الرَّجُلُ أَخَاهُ عَمْدًا لَمْ يُوَرَّثْ مِنْ مِيرَاثِهِ وَلَا مِنْ دِيَتِهِ فَإِذَا قَتَلَهُ خَطَأً وُرِّثَ مِنْ مِيرَاثِهِ وَلَمْ يُوَرَّثْ مِنْ دِيَتِهِ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عَطَاءٌ ‏ ‏يَقُولُ ذَلِكَ ‏","","",""],[2949,2949,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏رَمَى رَجُلٌ أُمَّهُ بِحَجَرٍ فَقَتَلَهَا فَطَلَبَ مِيرَاثَهُ مِنْ إِخْوَتِهِ فَقَالَ لَهُ إِخْوَتُهُ لَا مِيرَاثَ لَكَ فَارْتَفَعُوا إِلَى ‏ ‏عَلِيٍّ ‏ ‏فَجَعَلَ عَلَيْهِ الدِّيَةَ وَأَخْرَجَهُ مِنْ الْمِيرَاثِ ‏","","",""],[2950,2950,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ الْحُرِّ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏أَنَّ الرَّجُلَ إِذَا قَتَلَ امْرَأَتَهُ خَطَأً أَنَّهُ يُمْنَعُ مِيرَاثَهُ مِنْ ‏ ‏الْعَقْلِ ‏ ‏وَغَيْرِهِ ‏","","",""],[2951,2951,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَا يَرِثُ الْقَاتِلُ مِنْ الْمَقْتُولِ شَيْئًا ‏","","",""],[2952,2952,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏فِي رَجُلٍ قَذَفَ امْرَأَتَهُ وَجَاءَ بِشُهُودٍ فَرُجِمَتْ قَالَ ‏ ‏يَرِثُهَا ‏","","",""],[2953,2953,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏فِي رَجُلٍ جُلِدَ الْحَدَّ ‏ ‏أَرَاهُ مَاتَ شَكَّ ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ ‏ ‏يَتَوَارَثَانِ ‏","","",""],[2954,2954,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏الْقَاتِلُ لَا يَرِثُ وَلَا ‏ ‏يَحْجُبُ ‏","","",""],[2955,2955,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏لَا يُوَرَّثُ الْقَاتِلُ ‏","","",""],[2956,2956,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏لَا يَرِثُ قَاتِلٌ خَطَأً وَلَا عَمْدًا ‏","","",""],[2957,2957,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَا يَرِثُ الْقَاتِلُ ‏","","",""],[2958,2958,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏إِذَا اجْتَمَعَ نَسَبَانِ وُرِّثَ بِأَكْبَرِهِمَا ‏ ‏يَعْنِي ‏ ‏الْمَجُوسَ ‏","","",""],[2959,2959,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ أَبِي سُلَيْمَانَ ‏ ‏قَالَ ‏ ‏يَرِثُ مِنْ الْجَانِبِ الَّذِي يَصْلُحُ وَلَا يَرِثُ مِنْ الْجَانِبِ الَّذِي لَا يَصْلُحُ ‏","","",""],[2960,2960,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏وَابْنَ مَسْعُودٍ ‏ ‏قَالَا فِي ‏ ‏الْمَجُوسِ ‏ ‏إِذَا أَسْلَمُوا يَرِثُونَ مِنْ الْقَرَابَتَيْنِ جَمِيعًا ‏","","",""],[2961,2961,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏فِي امْرَأَةِ الْأَسِيرِ أَنَّهَا ‏ ‏تَرِثُهُ وَيَرِثُهَا ‏","","",""],[2962,2962,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنِي ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏فِي الْأَسِيرِ يُوصِي قَالَ ‏ ‏أَجِزْ لَهُ وَصِيَّتَهُ مَا دَامَ عَلَى دِينِهِ لَمْ يَتَغَيَّرْ عَنْ دِينِهِ ‏","","",""],[2963,2963,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏شُرَيْحٍ ‏ ‏قَالَ ‏ ‏يُوَرَّثُ الْأَسِيرُ إِذَا كَانَ فِي أَيْدِي الْعَدُوِّ ‏","","",""],[2964,2964,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏إِبْرَاهِيمَ ‏ ‏يَقُولُ ‏ ‏يُوَرَّثُ الْأَسِيرُ ‏","","",""],[2965,2965,"","","‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُ كَانَ لَا يُوَرِّثُ الْأَسِيرَ ‏","","",""],[2966,2966,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْعَثُ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏إِلَى ‏ ‏شُرَيْحٍ ‏ ‏أَنْ ‏ ‏لَا يُوَرِّثَ ‏ ‏الْحَمِيلَ ‏ ‏إِلَّا ‏ ‏بِبَيِّنَةٍ ‏ ‏وَإِنْ جَاءَتْ بِهِ فِي خِرَقِهَا ‏","","",""],[2967,2967,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏وَرِّثْ ‏ ‏الْحَمِيلَ ‏","","",""],[2968,2968,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مِنْ ‏ ‏بَنِي أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ ‏ ‏وَالْفُضَيْلِ بْنِ فَضَالَةَ ‏ ‏وَابْنِ أَبِي عَوْفٍ ‏ ‏وَرَاشِدٍ ‏ ‏وَعَطِيَّةَ ‏ ‏قَالُوا ‏ ‏لَا يُوَرَّثُ ‏ ‏الْحُمَلَاءُ ‏","","",""],[2969,2969,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ عِنْدَهُ قَوْلُ مَنْ يَقُولُ فِي ‏ ‏الْحَمِيلِ ‏ ‏فَأَنْكَرَ ذَلِكَ وَقَالَ ‏ ‏قَدْ تَوَارَثَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَالْأَنْصَارُ ‏ ‏بِنَسَبِهِمْ الَّذِي كَانَ فِي الْجَاهِلِيَّةِ ‏","","",""],[2970,2970,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏عَنْ ‏ ‏ابْنِ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَابْنِ سِيرِينَ ‏ ‏قَالَا ‏ ‏لَا يُوَرَّثُ ‏ ‏الْحَمِيلُ ‏ ‏إِلَّا ‏ ‏بِبَيِّنَةٍ ‏","","",""],[2971,2971,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏يُوَرِّثُونَ ‏ ‏الْحَمِيلَ ‏","","",""],[2972,2972,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحِيمِ الْمُحَارِبِيُّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ أَبِي الشَّعْثَاءِ ‏ ‏قَالَ ‏ ‏أَقَرَّتْ امْرَأَةٌ مِنْ ‏ ‏مُحَارِبٍ ‏ ‏جَلِيبَةٌ ‏ ‏بِنَسَبٍ لَهَا ‏ ‏جَلِيبٍ ‏ ‏فَوَرَّثَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عُتْبَةَ ‏ ‏مِنْ أُخْتِهِ ‏","","",""],[2973,2973,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ رَجُلٍ قَالَ عِنْدَ فِرَاقِ الدُّنْيَا أَنَا ‏ ‏مَوْلَى ‏ ‏فُلَانٍ قَالَ ‏ ‏يَرِثُ مِيرَاثَهُ لِمَنْ سَمَّى أَنَّهُ ‏ ‏مَوْلَاهُ ‏ ‏عِنْدَ فِرَاقِ الدُّنْيَا إِلَّا أَنْ يَأْتُوا عَلَيْهِ ‏ ‏بِبَيِّنَةٍ ‏ ‏بِغَيْرِ ذَلِكَ يَرُدُّونَ بِهِ قَوْلَهُ فَيُرَدُّ مِيرَاثُهُ إِلَى مَا قَامَتْ بِهِ ‏ ‏الْبَيِّنَةُ ‏","","",""],[2974,2974,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَعَبْدِ اللَّهِ ‏ ‏قَالَا ‏ ‏وَلَدُ الزِّنَا بِمَنْزِلَةِ ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏","","",""],[2975,2975,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ الْحُرِّ ‏ ‏حَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏أَنَّ وَلَدَ الزِّنَا لَا يَرِثُهُ الَّذِي ‏ ‏يَدَّعِيهِ وَلَا يَرِثُهُ الْمَوْلُودُ ‏","","",""],[2976,2976,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي حَفْصَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏لَا يُوَرِّثُ وَلَدَ الزِّنَا وَإِنْ ادَّعَاهُ الرَّجُلُ ‏","","",""],[2977,2977,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏أَيُّمَا رَجُلٍ أَتَى إِلَى غُلَامٍ يَزْعُمُ أَنَّهُ ابْنٌ لَهُ وَأَنَّهُ زَنَى بِأُمِّهِ وَلَمْ يَدَّعِ ذَلِكَ الْغُلَامَ أَحَدٌ فَهُوَ يَرِثُهُ ‏ ‏قَالَ ‏ ‏بُكَيْرٌ ‏ ‏وَسَأَلْتُ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ذَلِكَ ‏ ‏فَقَالَ مِثْلَ قَوْلِ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏وَقَالَ ‏ ‏عُرْوَةُ ‏ ‏بَلَغَنَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ الْحَجَرُ ‏","","",""],[2978,2978,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ غِيَاثٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏ابْنُ ‏ ‏الْمُلَاعَنَةِ ‏ ‏مِثْلُ وَلَدِ الزِّنَا تَرِثُهُ أُمُّهُ وَوَرَثَتُهُ وَرَثَةُ أُمِّهِ ‏","","",""],[2979,2979,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لَا يُوَرَّثُ وَلَدُ الزِّنَا ‏","","",""],[2980,2980,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏أَوْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏فِي أَوْلَادِ الزِّنَا قَالَ ‏ ‏يَتَوَارَثُونَ مِنْ قِبَلِ الْأُمَّهَاتِ وَإِنْ وَلَدَتْ تَوْأَمًا فَمَاتَ وَرِثَ السُّدُسَ ‏","","",""],[2981,2981,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏شِبَاكٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لَا يَرِثُ وَلَدُ الزِّنَا لَا يَرِثُ مَنْ لَمْ يُقَمْ عَلَى أَبِيهِ الْحَدُّ أَوْ تُمْلَكُ أُمُّهُ بِنِكَاحٍ أَوْ شِرَاءٍ ‏","","",""],[2982,2982,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبَانَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ مُحَمَّدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الرَّجُلِ ‏ ‏يَفْجُرُ ‏ ‏بِالْمَرْأَةِ ثُمَّ يَتَزَوَّجُهَا قَالَ ‏ ‏لَا بَأْسَ إِلَّا أَنْ تَكُونَ حُبْلَى فَإِنَّ الْوَلَدَ لَا يَلْحَقُهُ ‏","","",""],[2983,2983,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى ‏ ‏أَنَّ لِكُلِّ مُسْتَلْحَقٍ اسْتُلْحِقَ بَعْدَ أَبِيهِ الَّذِي ادَّعَاهُ وَرَثَتُهُ بَعْدَهُ فَقَضَى إِنْ كَانَ مِنْ أَمَةٍ يَمْلِكُهَا يَوْمَ يَطَؤُهَا فَقَدْ لَحِقَ بِمَنْ اسْتَلْحَقَهُ وَلَيْسَ لَهُ مِمَّا قُسِمَ قَبْلَهُ مِنْ الْمِيرَاثِ شَيْءٌ وَمَا أَدْرَكَ مِنْ مِيرَاثٍ لَمْ يُقْسَمْ فَلَهُ نَصِيبُهُ وَلَا يَلْحَقُ إِذَا كَانَ الَّذِي يُدْعَى لَهُ أَنْكَرَهُ وَإِنْ كَانَ مِنْ أَمَةٍ لَا يَمْلِكُهَا أَوْ حُرَّةٍ ‏ ‏عَاهَرَهَا ‏ ‏فَإِنَّهُ لَا يَلْحَقُ وَلَا يَرِثُ وَإِنْ كَانَ الَّذِي يُدْعَى لَهُ هُوَ ادَّعَاهُ وَهُوَ وَلَدُ زِنَا لِأَهْلِ أُمِّهِ مَنْ كَانُوا حُرَّةً أَوْ أَمَةً ‏","","",""],[2984,2984,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُمَيْرِ بْنِ يَزِيدَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏عَنْ مَمْلُوكٍ لِي وَلَدُ زِنًا قَالَ ‏ ‏لَا تَبِعْهُ وَلَا تَأْكُلْ ثَمَنَهُ وَاسْتَخْدِمْهُ ‏","","",""],[2985,2985,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏سُئِلَ عَنْ وَلَدِ زِنَا يَمُوتُ قَالَ ‏ ‏إِنْ كَانَ ابْنَ عَرَبِيَّةٍ وَرِثَتْ أُمُّهُ الثُّلُثَ وَجُعِلَ بَقِيَّةُ مَالِهِ فِي بَيْتِ الْمَالِ وَإِنْ كَانَ ابْنَ ‏ ‏مَوْلَاةٍ ‏ ‏وَرِثَتْ أُمُّهُ الثُّلُثَ وَوَرِثَ مَوَالِيهَا الَّذِينَ أَعْتَقُوهَا مَا بَقِيَ ‏ ‏قَالَ ‏ ‏مَرْوَانُ ‏ ‏سَمِعْتُ ‏ ‏مَالِكًا ‏ ‏يَقُولُ ذَلِكَ ‏","","",""],[2986,2986,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِمِيرَاثِ ابْنِ ‏ ‏الْمُلَاعَنَةِ ‏ ‏لِأُمِّهِ كُلِّهِ لِمَا لَقِيَتْ فِيهِ مِنْ الْعَنَاءِ ‏","","",""],[2987,2987,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبَانَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ مُحَمَّدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ حَصِيرَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّهُ قَالَ فِي وَلَدِ الزِّنَا ‏ ‏لِأَوْلِيَاءِ ‏ ‏أُمِّهِ ‏ ‏خُذُوا ابْنَكُمْ تَرِثُونَهُ ‏ ‏وَتَعْقِلُونَهُ ‏ ‏وَلَا يَرِثُكُمْ ‏","","",""],[2988,2988,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏السَّائِبَةُ ‏ ‏يَضَعُ مَالَهُ حَيْثُ شَاءَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَمْ يَسْمَعْ هَذَا مِنْ ‏ ‏سَلَمَةَ ‏ ‏أَحَدٌ غَيْرِي ‏","","",""],[2989,2989,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ وَرْدَانَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏سُئِلَ عَنْ مِيرَاثِ ‏ ‏السَّائِبَةِ ‏ ‏فَقَالَ ‏ ‏كُلُّ عَتِيقٍ ‏ ‏سَائِبَةٌ ‏","","",""],[2990,2990,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏الصَّدَقَةُ ‏ ‏وَالسَّائِبَةُ ‏ ‏لِيَوْمِهِمَا ‏","","",""],[2991,2991,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏عَامِرٌ ‏ ‏عَنْ الْمَمْلُوكِ يُعْتَقُ ‏ ‏سَائِبَةً ‏ ‏لِمَنْ ‏ ‏وَلَاؤُهُ ‏ ‏قَالَ ‏ ‏لِلَّذِي أَعْتَقَهُ ‏","","",""],[2992,2992,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَاتِمٍ الْبَصْرِيُّ هُوَ رَوْحُ بْنُ أَسْلَمَ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏مَاتَ ‏ ‏مَوْلًى ‏ ‏عَلَى عَهْدِ ‏ ‏عُثْمَانَ ‏ ‏وَلَيْسَ لَهُ ‏ ‏وَالٍ ‏ ‏فَأَمَرَ بِمَالِهِ فَأُدْخِلَ بَيْتَ الْمَالِ ‏","","",""],[2993,2993,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏فِي رَجُلٍ مَاتَ وَلَمْ يَكُنْ لَهُ ‏ ‏مَوْلَى عَتَاقَةٍ ‏ ‏قَالَ ‏ ‏مَالُهُ حَيْثُ أَوْصَى بِهِ فَإِنْ لَمْ يَكُنْ أَوْصَى فَهُوَ فِي بَيْتِ الْمَالِ ‏","","",""],[2994,2994,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ ‏ ‏وَرَاشِدِ بْنِ سَعْدٍ ‏ ‏وَغَيْرِهِمَا ‏ ‏قَالُوا فِيمَنْ أُعْتِقَ ‏ ‏سَائِبَةً ‏ ‏إِنَّ ‏ ‏وَلَاءَهُ ‏ ‏لِمَنْ أَعْتَقَهُ إِنَّمَا ‏ ‏سَيَّبَهُ ‏ ‏مِنْ الرِّقِّ وَلَمْ ‏ ‏يُسَيِّبْهُ ‏ ‏مِنْ ‏ ‏الْوَلَاءِ ‏","","",""],[2995,2995,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَالشَّعْبِيِّ ‏ ‏قَالَا ‏ ‏لَا بَأْسَ بِبَيْعِ ‏ ‏وَلَاءِ ‏ ‏السَّائِبَةِ ‏ ‏وَهِبَتِهِ ‏","","",""],[2996,2996,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏قَالَ ‏ ‏أَعْتَقَ رَجُلٌ غُلَامًا ‏ ‏سَائِبَةً ‏ ‏فَأَتَى ‏ ‏عَبْدَ اللَّهِ ‏ ‏وَقَالَ إِنِّي أَعْتَقْتُ غُلَامًا لِي ‏ ‏سَائِبَةً ‏ ‏وَهَذِهِ تَرِكَتُهُ قَالَ ‏ ‏هِيَ لَكَ قَالَ لَا حَاجَةَ لِي فِيهَا قَالَ فَضَعْهَا فَإِنَّ هَا هُنَا وَارِثًا كَثِيرًا ‏","","",""],[2997,2997,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَشْعَثُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏اسْتَهَلَّ ‏ ‏الصَّبِيُّ وُرِّثَ وَصُلِّيَ عَلَيْهِ ‏","","",""],[2998,2998,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏اسْتَهَلَّ ‏ ‏الصَّبِيُّ وَرِثَ وَوُرِثَ وَصُلِّيَ عَلَيْهِ ‏","","",""],[2999,2999,"","","‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنْ مَوْلُودٍ إِلَّا ‏ ‏يَسْتَهِلُّ ‏ ‏وَاسْتِهْلَالُهُ ‏ ‏يَعْصِرُ الشَّيْطَانُ بَطْنَهُ فَيَصِيحُ إِلَّا ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏","","",""],[3000,3000,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى هُوَ ابْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَاقِدٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَرِثُ الْمَوْلُودُ حَتَّى يَسْتَهِلَّ صَارِخًا وَإِنْ وَقَعَ حَيًّا ‏","","",""]];
